import zipfile
p='documents/turn-2-redline-meridian.docx'
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with zipfile.ZipFile(p) as z: root=etree.fromstring(z.read('word/document.xml'))
for i,p in enumerate(root.xpath('//w:body/w:p',namespaces=ns)):
    parts=[]
    for node in p.xpath('.//w:t|.//w:delText',namespaces=ns):
        txt=node.text or ''
        anc=node.getparent()
        while anc is not None and anc.tag not in ['{http://schemas.openxmlformats.org/wordprocessingml/2006/main}ins','{http://schemas.openxmlformats.org/wordprocessingml/2006/main}del']:
            anc=anc.getparent()
        typ='INS' if anc is not None and anc.tag.endswith('ins') else 'DEL' if anc is not None else 'DIR'
        parts.append((typ,txt))
    if any(k.lower() in ''.join(x[1] for x in parts).lower() for k in ['haircut','margin threshold','cross-default','act of insolvency','repricing','mini close','dispute resolution','high court','substitution','lcia']):
        print('\nP',i)
        print(''.join(f'[{typ}:{txt}]' if typ!='DIR' else txt for typ,txt in parts))
PY","description":"Extract relevant Turn 2 tracked text","timeoutMs":120000}

